@page "/track"
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2>Track a Shipment</h2>

<div class="mb-3 d-flex gap-2">
    <input type="text" class="form-control" style="max-width: 300px;" placeholder="Enter tracking number"
           @bind="trackingNumber" @bind:event="oninput" />
    <button class="btn btn-primary" @onclick="Search" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">Search</button>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">No shipment found for tracking number "@trackingNumber".</div>
}

@if (shipment is not null)
{
    <div class="card mt-3" style="max-width: 500px;">
        <div class="card-body">
            <h5 class="card-title">@shipment.TrackingNumber</h5>
            <p><strong>Origin:</strong> @shipment.Origin</p>
            <p><strong>Destination:</strong> @shipment.Destination</p>
            <p><strong>Status:</strong> <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></p>
            <p><strong>Shipped Date:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</p>
            <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</p>
        </div>
    </div>
}

@code {
    private string trackingNumber = string.Empty;
    private Shipment? shipment;
    private bool searched;

    private async Task Search()
    {
        searched = true;
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };
}

@page "/dispatch"
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatch Dashboard</PageTitle>

<h2>Dispatch Dashboard</h2>

<button class="btn btn-success mb-3" @onclick="ToggleNewForm">@(showForm ? "Cancel" : "New Shipment")</button>

@if (showForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create Shipment</h5>
            <div class="row g-2">
                <div class="col-md-4">
                    <input class="form-control" placeholder="Tracking Number" @bind="newShipment.TrackingNumber" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Origin" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Destination" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Customer Email" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-4">
                    <input class="form-control" placeholder="Description" @bind="newShipment.Description" />
                </div>
                <div class="col-md-4">
                    <input type="date" class="form-control" @bind="newShipment.EstimatedDelivery" />
                </div>
                <div class="col-12 mt-2">
                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p>Loading...</p>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
                <th>Update Status</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in shipments)
            {
                <tr>
                    <td>@s.TrackingNumber</td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                value="@((int)s.Status)"
                                @onchange="(e) => UpdateStatus(s, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@((int)status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    private List<Shipment>? shipments;
    private Shipment newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private bool showForm;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ToggleNewForm() => showForm = !showForm;

    private async Task CreateShipment()
    {
        newShipment.ShippedDate = DateTime.UtcNow;
        await ShipmentService.CreateShipmentAsync(newShipment);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showForm = false;
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-info",
        ShipmentStatus.OutForDelivery => "bg-primary",
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        _ => "bg-secondary"
    };
}

